import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.AuRYXM_l.js";const u=JSON.parse('{"title":"Chainy documentation website","description":"The public website is hosted at https://owenlim225.github.io/Chainy-Docs/. The private Chainy repository remains the source of truth. The public Chainy-Docs repository contain","frontmatter":{"title":"Chainy documentation website","description":"The public website is hosted at https://owenlim225.github.io/Chainy-Docs/. The private Chainy repository remains the source of truth. The public Chainy-Docs repository contain","source":"tools/docs-viewer/README.md","category":"Guides & tooling","sourceUpdated":"2026-10-08T06:48:18+08:00","outline":[2,3]},"headers":[],"relativePath":"content/tools/docs-viewer/readme.md","filePath":"content/tools/docs-viewer/readme.md"}'),n={name:"content/tools/docs-viewer/readme.md"};function s(r,e,d,c,l,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-documentation-website">Chainy documentation website<a class="header-anchor" href="#chainy-documentation-website" aria-label="Link to this section">​</a></h1><p>The public website is hosted at <a href="https://owenlim225.github.io/Chainy-Docs/">https://owenlim225.github.io/Chainy-Docs/</a>. The private Chainy repository remains the source of truth. The public Chainy-Docs repository contains generated output and its Pages workflow.</p><h2 id="local-development">Local development<a class="header-anchor" href="#local-development" aria-label="Link to this section">​</a></h2><p>Use Node 24 and run <code>npm ci</code>, then <code>npm run dev</code> from this directory. <code>npm run build</code> prepares the documents, builds the site and checks every generated document and internal link. <code>npm test</code> checks route handling and publication boundaries. <code>npm run preview</code> serves the production output locally. If the shared npm cache is unavailable, use <code>npm ci --cache .npm-cache</code>.</p><h2 id="adding-and-updating-documents">Adding and updating documents<a class="header-anchor" href="#adding-and-updating-documents" aria-label="Link to this section">​</a></h2><p>Edit the canonical Markdown files in this repository. All tracked or non-ignored project Markdown files are discovered automatically, including <code>.agents</code> skill guides and archived material. Viewer page templates, dependencies and generated files are excluded. Local previews include uncommitted documents; the automatic publisher only sees the committed checkout. Do not infer a verified change date for an uncommitted file.</p><p>The preparation script categorizes documents by source path, extracts the title and first paragraph, and builds stable routes. New files outside known categories appear under Other documents. Duplicate normalized routes fail the build. Relative links and heading fragments are validated; folder links produce directory pages. Archive documents retain their original wording and receive a historical notice.</p><p>The reader supports tables, task lists, highlighted code, images, Mermaid diagrams, heading links, local full-text search, document filters, sorting, dark mode and printing. Mermaid loads only when a document contains a diagram. The document source is escaped before rendering inside a Vue <code>v-pre</code> boundary so embedded HTML and interpolation remain content.</p><p>Linked SQL, publication JSON and project media are explicitly permitted in the preparation script. New asset types require a deliberate allowance. Do not add participant records, identity maps, credentials or signing keys to source documents or attachments. The entire published document text and search index are public even though the source repository is private.</p><h2 id="automatic-publication">Automatic publication<a class="header-anchor" href="#automatic-publication" aria-label="Link to this section">​</a></h2><p>The private repository workflow <code>.github/workflows/docs.yml</code> validates pull requests. On matching pushes to main or a manual run, it builds and publishes generated output to owenlim225/Chainy-Docs. The public repository&#39;s workflow then deploys that output through GitHub Pages. The base path is <code>/Chainy-Docs/</code>.</p><p>The publisher uses a dedicated write-enabled SSH deploy key installed only on Chainy-Docs. Its private half is stored as the Chainy Actions secret <code>DOCS_DEPLOY_KEY</code>; it is not a general GitHub account token. Pull-request jobs do not receive that credential. The initial plan proposed a GitHub App; the implementation uses a repository-scoped deploy key to avoid requiring an additional application installation.</p><p>Pages must use GitHub Actions as its publishing source. The public repo holds only <code>site/</code>, a generated README and <code>.github/workflows/pages.yml</code>. Builds are serialized. Validation failures prevent publication and leave the last successful site available. Read <code>publication.json</code> on the live website to identify its source revision and included document paths.</p><h2 id="troubleshooting-and-rollback">Troubleshooting and rollback<a class="header-anchor" href="#troubleshooting-and-rollback" aria-label="Link to this section">​</a></h2><p>Inspect the private Build and publish documentation workflow first, then the public Publish documentation workflow. A passing private build alone does not prove Pages deployed. Missing document paths, duplicate routes, broken heading links or credential-like content stop the build with a source filename. Fix the canonical source and rerun.</p><p>For rollback, revert the unwanted generated publication commit in Chainy-Docs and push main; Pages redeploys the previous output. To keep that rollback in place, pause the private publisher until the source correction is ready. Never use a force push to restore the site. The same publication pipeline can be exercised without changing content through workflow_dispatch.</p><h2 id="scope-and-evidence">Scope and evidence<a class="header-anchor" href="#scope-and-evidence" aria-label="Link to this section">​</a></h2><p>This is management tooling and does not establish game implementation progress. GitHub issues remain the execution record; backlog.json remains the publication inventory. Preserve the November 21, 2026 pre-final defense and the reserved integration, QA, pilot and rehearsal time.</p><p>Dependency versions are locked. Review dependency audit output when updating; the site is statically hosted and exposes no development server. Browser and workflow acceptance evidence is recorded in the viewer delivery issue, with any unverified checks stated explicitly.</p></div>',1)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
